const lief = n => { try { return $(n).isExecuted === true; } catch (e) { return false; } };
const zahl = v => (typeof v === 'number' && isFinite(v)) ? v : null;
const nimm = n => { try { const a = $(n).all(0); if (a.length) return a[0].json; const b = $(n).all(1); return b.length ? b[0].json : {}; } catch (e) { return { error: { message: 'Knoten ' + n + ' nicht lesbar: ' + e.message } }; } };

// ---------- Teil 1: Fakten (nur wenn Recherche Sonar lief) ----------
let fakt = { research_status: 'uebersprungen', research_text: '', research_sources: [], research_model: 'perplexity/sonar', research_tokens: null, research_fact_cost_usd: null, research_note: '' };
if (lief('Recherche Sonar [HTTP Request]')) {
  const r = ($input.first() || {}).json || {};
  const wahl = (Array.isArray(r.choices) ? r.choices : [])[0] || {};
  const msg = wahl.message || {};
  const text = String(msg.content || '').trim();
  // Warum zuerst die Adressen im Text: nur sie stehen hinter einer Aussage. annotations und citations enthalten auch unbenutzte Treffer (Hilfsaufrufe 754 bis 759).
  const urls = [];
  const add = u => { u = String(u || '').trim().replace(/[)\].,;]+$/, ''); if (/^https?:\/\/[^\s<>"']+$/.test(u) && !urls.includes(u)) urls.push(u); };
  for (const m of text.match(/https?:\/\/[^\s<>"')\]]+/g) || []) add(m);
  if (!urls.length) {
    for (const a of (Array.isArray(msg.annotations) ? msg.annotations : [])) add(a && (a.url_citation ? a.url_citation.url : a.url));
    for (const c of (Array.isArray(r.citations) ? r.citations : [])) add(typeof c === 'string' ? c : c && c.url);
  }
  const u = (r.usage && typeof r.usage === 'object') ? r.usage : {};
  const fehler = r.error ? String(r.error.message || r.error).slice(0, 160) : '';
  const keine = /KEINE BELEGTEN QUELLEN/i.test(text);
  // Warum mindestens 1 Adresse: ohne Beleg ist die Recherche nichts wert, das Paket bleibt dann beim bisherigen Weg (keine erfundenen Studien).
  const ok = !fehler && !keine && text.length >= 80 && urls.length >= 1;
  fakt = { research_status: ok ? 'ok' : 'fallback', research_text: ok ? text.replace(/\[(\d+)\]/g, '').slice(0, 2500) : '', research_sources: ok ? urls.slice(0, 8) : [],
    research_model: String(r.model || 'perplexity/sonar'), research_tokens: zahl(u.total_tokens), research_fact_cost_usd: zahl(u.cost),
    research_note: ok ? '' : ('R1: Recherche ohne verwertbares Ergebnis (' + (fehler || (keine ? 'Sonar fand keine belegten Quellen' : (text.length < 80 ? 'Antwort leer oder zu kurz' : 'keine Quellen-Adresse'))) + '), Paket ohne Recherche') };
}

// ---------- Teil 2: aktuelle Vorlagen (laeuft bei jedem Post) ----------
const v = nimm('Virale Posts Sonar [HTTP Request]');
const vMsg = (((Array.isArray(v.choices) ? v.choices : [])[0]) || {}).message || {};
const vText = String(vMsg.content || '').trim();
const vU = (v.usage && typeof v.usage === 'object') ? v.usage : {};
const vFehler = v.error ? String(v.error.message || v.error).slice(0, 160) : '';
// Warum Datumspruefung im Code: search_recency_filter week wirkt laut Messung (Hilfsaufrufe 781 gegen 782), trotzdem zaehlen nur Zeilen mit Datum in den letzten 8 Tagen (1 Tag Puffer fuer Zeitzonen).
const heute = Date.now();
const posts = [];
// Warum Quellenabgleich: ein Post zaehlt nur, wenn Sonar seine Adresse als gelesene Quelle (url_citation) meldet; eine nur im Text genannte Adresse ist kein Beleg.
// Warum nur Schema und Host klein: Pfade koennen gross- und kleinschreibungsabhaengig sein.
const normUrl = u => { const s = String(u || '').trim().replace(/[)\].,;]+$/, '').replace(/\/+$/, ''); const m = s.match(/^(https?:\/\/[^\/?#]+)(.*)$/i); return m ? m[1].toLowerCase() + m[2] : s; };
const gelesen = new Set([].concat(Array.isArray(vMsg.annotations) ? vMsg.annotations : [], Array.isArray(v.citations) ? v.citations : []).map(a => normUrl(typeof a === 'string' ? a : (a && (a.url_citation ? a.url_citation.url : a.url)))).filter(Boolean));
let unbelegt = 0;
for (const zeile of vText.split('\n')) {
  const m = zeile.match(/^\s*-\s*POST:\s*(.*)$/i);
  if (!m) continue;
  const teile = m[1].split('|').map(s => s.trim());
  const datum = (teile.find(t => /^\d{4}-\d{2}-\d{2}$/.test(t)) || '');
  const url = (teile.find(t => /^https?:\/\/\S+$/.test(t)) || '');
  const hook = ((teile.find(t => /^Hook:/i.test(t)) || '').replace(/^Hook:\s*/i, '')).slice(0, 220);
  const tags = ((teile.find(t => /^Hashtags:/i.test(t)) || '').match(/#[\p{L}\p{N}_]+/gu) || []);
  const alter = datum ? (heute - Date.parse(datum + 'T12:00:00Z')) / 86400000 : 99;
  if (!url || !hook || !(alter >= -1 && alter <= 8)) continue;
  if (!gelesen.has(normUrl(url))) { unbelegt++; continue; }
  posts.push({ platform: teile[0].slice(0, 40), date: datum, url, hook, hashtags: tags });
}
// Warum nur Hashtags aus den Post-Zeilen: die Sammelzeile HASHTAGS koennte Erfundenes enthalten; gezaehlt wird nur, was an einem gefundenen Post steht.
const tagMap = new Map();
for (const p of posts) for (const t of p.hashtags) if (!tagMap.has(t.toLowerCase())) tagMap.set(t.toLowerCase(), t);
const vTags = Array.from(tagMap.values()).slice(0, 10);
const kw = ((vText.match(/^\s*KEYWORDS:\s*(.*)$/im) || [])[1] || '').split(',').map(s => s.trim()).filter(s => s && s.length <= 40).slice(0, 8);
let vStatus = 'ok';
if (vFehler || !vText) vStatus = 'fehler';
else if (!posts.length) vStatus = 'keine';
const vNote = vStatus === 'ok' ? '' : (vStatus === 'fehler' ? 'R2: Vorlagen-Recherche gescheitert (' + (vFehler || 'Antwort leer') + '), Hashtags ohne Vorlage' : 'R2: keine aktuellen englischen Posts der letzten 7 Tage gefunden, Hashtags ohne Vorlage');
const viralText = vStatus !== 'ok' ? '' : posts.map(p => '- ' + p.platform + ', ' + p.date + ': ' + p.hook + (p.hashtags.length ? ' (' + p.hashtags.join(' ') + ')' : '')).join('\n')
  + '\nHashtags aus diesen Posts: ' + (vTags.length ? vTags.join(' ') : 'keine') + '\nKeywords dieser Posts: ' + (kw.length ? kw.join(', ') : 'keine');
const kosten = [fakt.research_fact_cost_usd, zahl(vU.cost)].filter(x => x != null);
// Warum Vollstaendigkeit (12.10.2026): fehlt bei einem beantworteten Sonar-Aufruf die Kostenangabe, ist die Summe nur eine Teilsumme und wird so gekennzeichnet.
const kostenFehlt = [];
// Warum unabhaengig vom Ergebnis: auch eine unbrauchbare Antwort oder ein Zeitlimit beweist keine kostenlose Anfrage.
if (lief('Recherche Sonar [HTTP Request]') && fakt.research_fact_cost_usd == null) kostenFehlt.push('Fakten-Sonar');
if (lief('Virale Posts Sonar [HTTP Request]') && zahl(vU.cost) == null) kostenFehlt.push('Vorlagen-Sonar');

return [{ json: Object.assign({}, fakt, {
  viral_status: vStatus, viral_posts: posts, viral_hashtags: vTags, viral_keywords: kw, viral_text: viralText.slice(0, 1800), viral_note: vNote,
  viral_cost_usd: zahl(vU.cost), viral_posts_unbelegt: unbelegt,
  // Warum zusammengezaehlt: die Protokollzeile addiert research_cost_usd zu den Modellkosten, beide Sonar-Aufrufe zaehlen zum Lauf.
  research_cost_usd: kosten.length ? Math.round(kosten.reduce((a, b) => a + b, 0) * 1e7) / 1e7 : null,
  research_cost_complete: kostenFehlt.length === 0, research_cost_missing: kostenFehlt
}), pairedItem: { item: 0 } }];

// Zweck: bis zu 3 Suchbegriffe fuer Pixabay bilden, damit Layout 4 Fotos zu verschiedenen Schlagwoertern bekommt:
// (1) photo_query des Modells, (2) Hauptwoerter aus den Folientexten, (3) Themenwort mit Pixabay-Kategorie (business, bei Gastro-Themen food).
// Warum Folientexte und Kategorie (12.10.2026, Layout 4 in Bk8): in den Laeufen 773 bis 775 passten Fotos nicht zum Inhalt (Maschinenteile bei
// Buero-Themen, Kinderfoto); Hilfsaufruf 792 zeigte, dass die Kategorie business Tierfotos zu "Rechnung" (Schnabel) aussortiert.
const basis = $('Branding-Variante wählen [Code]').first().json;
const q = String(basis.photo_query || '').trim();
const stop = new Set(['und', 'oder', 'mit', 'fuer', 'für', 'der', 'die', 'das', 'den', 'dem', 'des', 'ein', 'eine', 'einen', 'im', 'in', 'am', 'zu', 'von', 'bei', 'auf', 'aus',
  'schritt', 'schritte', 'tipp', 'tipps', 'jetzt', 'heute', 'warum', 'wie', 'was', 'dein', 'deine', 'deinen', 'ihre', 'mehr', 'weniger', 'ohne', 'durch', 'beitrag']);
const thema = String(basis.topic || '');
const gastro = /(caf[eé]|kaffee|restaurant|b[äa]cker|k[üu]che|essen|gastro|speise|kuchen|bistro|bar\b)/i.test(thema + ' ' + q);
const kategorie = gastro ? 'food' : 'business';
// Warum Grossschreibung: deutsche Hauptwoerter beginnen gross, das trennt Inhaltswoerter von Fuellwoertern ohne Sprachmodell.
const zaehler = new Map();
const folien = Array.isArray(basis.slides) ? basis.slides.slice(1, -1) : [];
for (const f of folien) {
  const text = String((f && f.heading) || '') + ' ' + String((f && f.text) || '');
  for (const w of text.replace(/[^\p{L}\p{N}\s-]/gu, ' ').split(/\s+/)) {
    if (w.length < 5 || !/^\p{Lu}/u.test(w) || stop.has(w.toLowerCase())) continue;
    zaehler.set(w, (zaehler.get(w) || 0) + 1);
  }
}
const folienWoerter = Array.from(zaehler.entries()).sort((a, b) => b[1] - a[1] || b[0].length - a[0].length).map(x => x[0]);
const themaWoerter = thema.replace(/[^\p{L}\p{N}\s-]/gu, ' ').split(/\s+/).filter(x => x.length > 5 && !stop.has(x.toLowerCase())).sort((a, b) => b.length - a.length);
const liste = [];
const add = (s, kat) => { s = String(s || '').trim(); if (s && !liste.some(x => x.q.toLowerCase() === s.toLowerCase())) liste.push({ q: s, kat }); };
add(q, '');
if (folienWoerter.length) add(folienWoerter.slice(0, 2).join(' '), '');
add(themaWoerter[0] || folienWoerter[2] || q, kategorie);
// Warum mindestens ein Element: ohne Suchbegriff laeuft der bisherige Weg (Pixabay ohne Treffer, weiter mit FLUX), die Kette darf nicht leer enden
if (!liste.length) liste.push({ q: '', kat: '' });
return liste.slice(0, 3).map((s, i) => ({ json: { ...basis, photo_query: s.q, photo_category: s.kat, photo_query_index: i }, pairedItem: { item: 0 } }));

// Zweck: Layout 4 (Baukasten v3) je Beitrag wuerfeln: bis zu 5 Folienplaene nach den Zufallsregeln des eigenen Layout-Baukastens plus der Rueckfallplan v2,
// je Plan eine Pruefseite (?pruefen=1) fuer Gotenberg. Branding bleibt fest, nur der Aufbau wechselt (Patrick 11.10.2026 abends).
// Warum Fehlerausgang statt Wurf ins Leere: jeder Wurf fuehrt ueber "Rueckfall altes Layout" zum bisherigen Layout.
const helpers = this.helpers;
const items = $input.all();
const paket = $('Branding-Variante wählen [Code]').first().json;
if (!paket.layout4_aktiv) throw new Error('LAYOUT4_AUS: Layout 4 ist fuer diesen Lauf nicht gewaehlt');
const k = paket.customer || {};
const pack = paket.branding_pack || {};
const hinweise = [];

// ---------- Branding: Schluessel des branding_pack auf die Vorlage abbilden (keine Schemaaenderung) ----------
// Warum Mapping: die Vorlage kennt grund_1/grund_2, der branding_pack hintergrund/hintergrund_2.
// Layout 4 ist ein dunkles Layout. Ist der Kunde hell (Ordwin #F4FBF7), gilt die dunkle Kundenfassung wie in v2:
// Grund #1A1A1A, Kapitel 2 im dunklen Markentext-Ton, heller Hintergrund wird Textfarbe.
const F0 = pack.farben || {};
const hex = v => (/^#[0-9a-fA-F]{6}$/.test(v || '') ? v : null);
const lum = h => { const c = [1, 3, 5].map(i => parseInt(h.substr(i, 2), 16) / 255).map(v => v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)); return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2]; };
const akzent = hex(F0.akzent) || '#22A26F', primaer = hex(F0.primaer) || akzent, sekundaer = hex(F0.sekundaer) || primaer;
let farben;
if (hex(F0.grund_1) && hex(F0.grund_2)) {
  farben = { grund_1: F0.grund_1, grund_2: F0.grund_2, text: hex(F0.text) || '#F4FBF7', text_gedimmt: hex(F0.text_gedimmt) || hex(F0.text) || '#E6E6E6' };
} else if (hex(F0.hintergrund) && lum(F0.hintergrund) < 0.2) {
  farben = { grund_1: hex(F0.hintergrund_2) || F0.hintergrund, grund_2: F0.hintergrund, text: hex(F0.text) || '#F2EEE8', text_gedimmt: hex(F0.text_gedimmt) || hex(F0.text) || '#DFDAD5' };
} else {
  const dunkel = hex(F0.text) && lum(F0.text) < 0.05 ? F0.text : '#111111';
  farben = { grund_1: '#1A1A1A', grund_2: dunkel, text: hex(F0.hintergrund) || '#F4FBF7', text_gedimmt: '#E6E6E6' };
}
Object.assign(farben, { akzent, primaer, sekundaer, schatten: 'rgba(0,0,0,.55)' });

// ---------- Schriften als base64 (fontsource ueber jsdelivr, gemessen Lauf 767: helpers.httpRequest laedt woff2) ----------
const sTitelRoh = (pack.schriften && pack.schriften.titel) || k.schrift_titel || 'IBM Plex Sans';
const sText = (pack.schriften && pack.schriften.text) || k.schrift_text || 'IBM Plex Sans';
// Warum Condensed: die Vorlage lebt von einer schmalen Titelschrift; fuer IBM Plex Sans die schmale Schwester derselben Familie (v2 README).
const sTitel = sTitelRoh === 'IBM Plex Sans' ? 'IBM Plex Sans Condensed' : sTitelRoh;
const slug = n => String(n).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const VERSION = { 'ibm-plex-sans': '@5.0.20', 'ibm-plex-sans-condensed': '@5.0.13' };
const fontUrl = (n, w) => 'https://cdn.jsdelivr.net/npm/@fontsource/' + slug(n) + (VERSION[slug(n)] || '') + '/files/' + slug(n) + '-latin-' + w + '-normal.woff2';
const laden = async (url, max) => {
  const r = await helpers.httpRequest({ url, encoding: 'arraybuffer', timeout: 20000 });
  const b = Buffer.from(r);
  if (!b.length || b.length > max) throw new Error('Datei leer oder zu gross: ' + b.length);
  return b;
};
let fontCss = '';
for (const [name, w] of [[sTitel, 700], [sText, 700], [sText, 600]]) {
  const b = await laden(fontUrl(name, w), 600000);
  if (b.subarray(0, 4).toString('latin1') !== 'wOF2') throw new Error('Schrift ist kein woff2: ' + name + ' ' + w);
  fontCss += '@font-face{font-family:"' + name.replace(/"/g, '') + '";font-weight:' + w + ';font-style:normal;font-display:block;src:url(data:font/woff2;base64,' + b.toString('base64') + ') format("woff2")}';
}

// ---------- Logo aus der Render-Liste (die Folien tragen es schon als Data-URI) ----------
let logo = '';
try {
  const html0 = (await helpers.getBinaryDataBuffer(0, 'index_html')).toString('utf8');
  const m = html0.match(/<div class="kopf"><img src="(data:image\/[a-z+]+;base64,[A-Za-z0-9+\/=]+)"/);
  if (m) logo = m[1]; else hinweise.push('L4: kein Logo in der Render-Liste, Medaillon mit Markenname');
} catch (e) { hinweise.push('L4: Logo nicht lesbar (' + String(e.message).slice(0, 60) + ')'); }
const einzel = items.find(i => i.json.kind === 'einzelbild');
if (!einzel) throw new Error('Render-Liste ohne Einzelbild');
const einzelHtml = (await helpers.getBinaryDataBuffer(items.indexOf(einzel), 'index_html')).toString('utf8');

// ---------- Fotos: Hauptfoto aus Foto einbetten, weitere Treffer aus Foto auswerten (bis zu 5) ----------
const lief = n => { try { return $(n).isExecuted === true; } catch (e) { return false; } };
const fotos = [];
if (lief('Foto einbetten [Code]')) {
  const fe = $('Foto einbetten [Code]').first().json;
  if (fe.photo_data_uri) fotos.push({ uri: fe.photo_data_uri, credit: fe.photo_credit || null, pid: fe.photo_credit && fe.photo_credit.photo_id });
}
const kandidaten = lief('Foto auswerten [Code]') ? ($('Foto auswerten [Code]').first().json.photo_candidates || []) : [];
const sicher = s => typeof s === 'string' && /^https:\/\/(cdn\.)?pixabay\.com\/[^\s"'<>]*$/.test(s);
let fotoFehler = 0;
for (const c of kandidaten) {
  if (fotos.length >= 5) break;
  if (!sicher(c.url) || fotos.some(f => f.pid === c.photo_id)) continue;
  try {
    const b = await laden(c.url, 8 * 1024 * 1024);
    const jpeg = b[0] === 255 && b[1] === 216 && b[2] === 255;
    const png = b.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]));
    if (!jpeg && !png) throw new Error('kein JPEG/PNG');
    fotos.push({ uri: 'data:' + (png ? 'image/png' : 'image/jpeg') + ';base64,' + b.toString('base64'), credit: { photographer: c.user, source: 'Pixabay', pixabay_url: c.page, photo_id: c.photo_id }, pid: c.photo_id });
  } catch (e) { fotoFehler++; }
}
if (fotoFehler) hinweise.push('L4: ' + fotoFehler + ' Zusatzfoto(s) nicht ladbar');

// ---------- Gedaechtnis: letzte 3 Fingerabdruecke desselben Kunden ----------
let gedaechtnis = [];
if (lief('Letzte Aufbauten laden [HTTP Request]')) {
  const g = $('Letzte Aufbauten laden [HTTP Request]').first().json;
  if (Array.isArray(g.body)) gedaechtnis = g.body.map(z => (String(z.error_text || '').match(/L4:(t=[^;\s]+)/) || [])[1]).filter(Boolean).slice(0, 3);
  else hinweise.push('L4: Gedaechtnis nicht lesbar (Status ' + (g.statusCode || g.error && g.error.message || 'unbekannt') + ')');
}

// ---------- Zufall mit festem Startwert (wiederholbar je Beitrag) ----------
const hash = s => { let h = 2166136261; for (const ch of String(s)) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); } return h >>> 0; };
const zufall = seed => () => { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; };

// ---------- Texte aus dem Modell-Paket ----------
const rein = s => String(s == null ? '' : s).replace(/\*/g, '').replace(/\s+/g, ' ').trim();
const kurz = (s, n) => { s = rein(s); return s.length > n ? s.slice(0, n - 1).replace(/\s+\S*$/, '') + '…' : s; };
// erster Satzteil in Akzent (Stil-DNA "text_zweifarbig")
const akz = s => { s = rein(s); const m = s.match(/^(.{12,90}?[,:.!?])\s/); return m ? '*' + m[1] + '* ' + s.slice(m[0].length) : s; };
const condensed = /condensed|narrow|compressed|oswald|anton|bebas|league gothic/i.test(sTitel);
// Faktoren gemessen (lokaler Pruefmodus 12.10.2026): Versalien Plex Condensed 700 rund 0,59 em je Zeichen, mit Reserve 0,62
const fT = condensed ? 0.62 : 0.72, fX = 0.58;
// Warum ohne Leerzeichen nach Bindestrich: lange Komposita (FEHLER-WORKFLOW) duerfen am vorhandenen Bindestrich umbrechen, sonst keine Trennung
const umbrechen = (woerterListe, max) => { const z = []; let a = ''; for (const w of woerterListe) { const sep = a.endsWith('-') ? '' : ' '; if (!a) a = w; else if ((a + sep + w).length <= max) a += sep + w; else { z.push(a); a = w; } } if (a) z.push(a); return z; };
const zeilenText = (s, breite, px) => { const max = Math.max(8, Math.floor(breite / (px * fX))); return umbrechen(rein(s).split(' '), max).length; };
// Titel: feste Zeilen ohne Trennung, Schriftgroesse so, dass die laengste Zeile passt (Vorlage misst den Rest im Pruefmodus)
// Warum kuerzen erst im zweiten Durchgang (Lauf 770): sonst gewinnt ein abgeschnittener Titel gegen eine kleinere Schrift
const titelSetzen = (s, breite, px0, pxMin, maxZ, kuerzen) => {
  for (const t of kuerzen ? [kurz(s, 50), kurz(s, 38)] : [rein(s)]) {
    const w = t.toUpperCase().split(' ').filter(Boolean).flatMap(x => x.length > 8 && /[A-ZÄÖÜ]-[A-ZÄÖÜ]/.test(x) ? x.split(/(?<=-)/) : [x]);
    for (let px = px0; px >= pxMin; px -= 4) {
      const max = Math.floor((breite - 20) / (px * fT));
      if (w.some(x => x.length > max)) continue;
      const z = umbrechen(w, max);
      if (z.length <= maxZ) return { zeilen: z, px, ok: true };
    }
  }
  return { ok: false };
};
const markiere = z => z.map((x, i) => (z.length >= 2 && i === 1) || (z.length === 1) ? '*' + x + '*' : x);
const sl = Array.isArray(paket.slides) ? paket.slides : [];
if (sl.length < 5) throw new Error('Paket mit weniger als 5 Folien');
const titelF = sl[0], schlussF = sl[sl.length - 1], inhalt = sl.slice(1, -1);
const keyPoints = (paket.key_points || []).map(x => kurz(x, 110)).filter(Boolean);
// Warum process_steps (12.10.2026): bei Ablauf-Themen zeigt die Zusammenfassung den Ablauf statt der Kernaussagen (Paket prueft die Schritte schon).
const schritte = Array.isArray(paket.process_steps) ? paket.process_steps.map(x => kurz(x, 110)).filter(Boolean) : [];
// Warum (Lauf 774): Label "Schritt 1" und Titel "Schritt 1: ..." standen doppelt; die Marke traegt die Nummer, der Titel nicht.
const ohneSchritt = s => String(s || '').replace(/^\s*(schritt|step)\s*\d+\s*[:.)–—-]?\s*/i, '');

// Hoehen schaetzen (px): Block oben + Kopf + Titel + Text, Grenze 1180 (Vorlage meldet ab 1200 ZU TIEF)
const schrittSetzen = (f, nr, variante) => {
