<body>
<div class="leinwand" id="leinwand"></div>
<!--PLAN-->
<script>/*ABFRAGE*/</script>
<script>
(function(){
'use strict';
var BREITE = 1080, HOEHE = 1350;
var p = new URLSearchParams(window.__ABFRAGE || location.search);

/* ---------- Hilfen ---------- */
function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
/* *Wort* = Akzent. Mehr Markup gibt es nicht, damit das Sprachmodell nichts kaputtmachen kann. */
function md(s){ return esc(s).replace(/\*([^*]+)\*/g, '<span class="a">$1</span>'); }
function zeilen(arr){ return (Array.isArray(arr) ? arr : [arr]).map(function(z){ return '<span class="zeile">' + md(z) + '</span>'; }).join(''); }
function fliess(s, extra){ return '<p class="fliess"' + (extra ? ' style="' + extra + '"' : '') + '>' + md(s) + '</p>'; }

function ladePlan(){
  var inline = document.getElementById('plan');
  if (inline) return Promise.resolve(JSON.parse(inline.textContent));
  var datei = p.get('plan');
  if (!datei) return Promise.reject(new Error('kein Plan: ?plan=datei.json oder <script id="plan">'));
  return new Promise(function(ok, fehler){
    var x = new XMLHttpRequest();
    x.open('GET', datei, true);
    x.onload = function(){ try { ok(JSON.parse(x.responseText)); } catch(e){ fehler(e); } };
    x.onerror = function(){ fehler(new Error('Plan nicht ladbar: ' + datei)); };
    x.send();
  });
}

function setzeBranding(b){
  var f = b.farben || {}, r = document.documentElement.style;
  var map = { akzent:'--akzent', primaer:'--primaer', sekundaer:'--sekundaer', grund_1:'--grund-1', grund_2:'--grund-2', text:'--text', text_gedimmt:'--text-gedimmt', schatten:'--schatten' };
  Object.keys(map).forEach(function(k){ if (f[k]) r.setProperty(map[k], f[k]); });
  var s = b.schriften || {};
  if (s.titel) r.setProperty('--font-titel', '"' + s.titel + '", "DejaVu Sans Condensed", sans-serif');
  if (s.text) r.setProperty('--font-text', '"' + s.text + '", "DejaVu Sans", sans-serif');
  /* Schriften: in K1 als base64-@font-face im Dokument (dann kein Link noetig), lokal per Google-Fonts-Link.
     Gebaut wird erst, wenn beide Schriften geladen sind (hoechstens 8 s), sonst misst der Pruefmodus die Ersatzschrift. */
  var css = s.google_fonts_url ? new Promise(function(ok){
    var l = document.createElement('link'); l.rel = 'stylesheet'; l.href = s.google_fonts_url;
    l.onload = ok; l.onerror = function(){ console.warn('Schrift-CSS nicht ladbar'); ok(); };
    document.head.appendChild(l);
  }) : Promise.resolve();
  return css.then(function(){
    return Promise.race([
      Promise.all([document.fonts.load('700 100px "' + s.titel + '"'), document.fonts.load('700 40px "' + s.text + '"'), document.fonts.load('600 24px "' + s.text + '"')]),
      new Promise(function(ok){ setTimeout(ok, 8000); })
    ]);
  });
}

/* ---------- Regeln (gleiche Liste wie im eigenen Layout-Baukasten, Abschnitt Zufallsregeln) ---------- */
function istVollbild(f){ return (f.typ === 'titel' && f.variante === 'vollbild') || (f.typ === 'schritt' && f.variante === 'foto_hintergrund'); }
function regeln(plan){
  var w = [], F = plan.folien, N = F.length, U = plan.uebergaenge || [];
  if (N < 6 || N > 10) w.push('REGEL folienzahl ' + N + ' (erlaubt 6 bis 10)');
  if (F[0].typ !== 'titel') w.push('REGEL folie 1 muss titel sein');
  if (F[N-1].typ !== 'schluss') w.push('REGEL letzte folie muss schluss sein');
  if (F.filter(function(f){ return f.typ === 'speichern'; }).length !== 1) w.push('REGEL genau 1 speichern-folie');
  for (var i = 1; i < N; i++) if (istVollbild(F[i]) && istVollbild(F[i-1])) w.push('REGEL 2 vollbild-folien hintereinander: ' + i + '/' + (i+1));
  if (plan.kapitelwechsel_nach && N < 8) w.push('REGEL kapitelwechsel erst ab 8 folien');
  if (plan.kapitelwechsel_nach && F[plan.kapitelwechsel_nach].typ !== 'speichern') w.push('REGEL nach dem kapitelwechsel folgt die speichern-folie');
  if ((plan.fotos || []).length > 5) w.push('REGEL hoechstens 5 fotos');
  var arten = {}; U.forEach(function(u){ arten[u.art] = 1; });
  if (Object.keys(arten).length > 3) w.push('REGEL hoechstens 3 uebergangsarten');
  var jeKante = {};
  U.forEach(function(u){ kantenVon(u).forEach(function(k){ jeKante[k] = (jeKante[k] || 0) + 1; }); });
  if (plan.kapitelwechsel_nach) jeKante[plan.kapitelwechsel_nach] = (jeKante[plan.kapitelwechsel_nach] || 0) + 1;
  Object.keys(jeKante).forEach(function(k){ if (jeKante[k] > 3) w.push('REGEL kante ' + k + ' hat ' + jeKante[k] + ' elemente (max 3)'); });
  var nachKante = 0; Object.keys(jeKante).forEach(function(){ nachKante++; });
  if (nachKante < 2) w.push('REGEL mindestens 2 kanten mit uebergang');
  return w;
}
function kantenVon(u){
  if (u.art === 'zeitstrahl') { var k = []; for (var i = u.von; i < u.bis; i++) k.push(i); return k; }
  if (u.art === 'fotoband') return [u.von_folie];
  return [u.kante];
}

/* ---------- Fotos ---------- */
var FOTOS = {};
function img(id, extra){
  var f = FOTOS[id]; if (!f) return '';
  var fokus = f.fokus || '50% 50%', zoom = f.zoom || 1;
  return '<img src="' + esc(f.datei) + '" alt="" style="object-position:' + fokus + ';transform:scale(' + zoom + ');transform-origin:' + fokus + ';' + (f.spiegeln ? 'transform:scale(' + (-zoom) + ',' + zoom + ');' : '') + (extra || '') + '">';
}

/* ---------- Folien-Bausteine (liefern HTML in Folien-Koordinaten) ---------- */
var BAUSTEIN = {
  titel: function(f, i){
    var v = f.variante || 'typo';
    if (v === 'vollbild') {
      return '<div class="block" style="top:' + (f.titel_oben || 640) + 'px;width:920px"><h1 class="titel">' + zeilen(f.titel) + '</h1>' +
        (f.unter ? '<p class="unter" style="margin-top:34px;width:860px">' + md(f.unter) + '</p>' : '') + '</div>';
    }
    if (v === 'rahmen_kante') {
      return '<div class="block" style="top:150px;width:920px"><h1 class="titel">' + zeilen(f.titel) + '</h1></div>' +
        (f.unter ? '<p class="unter block" style="top:800px;width:540px">' + md(f.unter) + '</p>' : '');
    }
    /* typo: reine Schrift, Akzentbalken */
    return '<div class="balken" style="top:190px"></div><div class="block" style="top:250px;width:920px"><h1 class="titel">' + zeilen(f.titel) + '</h1>' +
      (f.unter ? '<p class="unter" style="margin-top:56px;width:760px">' + md(f.unter) + '</p>' : '') + '</div>';
  },
  bruecke: function(f){
    return '<div class="block" style="top:' + (f.oben || 130) + 'px;width:' + (f.breite || 860) + 'px"><h2 class="frage">' + zeilen(f.titel) + '</h2>' + fliess(f.text) + '</div>';
  },
  schritt: function(f){
    var v = f.variante || 'ziffer';
    var kopf = (v === 'ziffer' ? '<p class="marke">' + md(f.marke || ('Schritt ' + f.nr)) + '</p>' : '<span class="nummer">' + esc(String(f.nr).padStart(2, '0')) + '</span><p class="marke">' + md(f.marke || ('Schritt ' + f.nr)) + '</p>');
    var inhalt = kopf + '<h2 class="titel">' + zeilen(f.titel) + '</h2>' + fliess(f.text);
    if (v === 'ziffer') return '<div class="ziffer hindernis" aria-hidden="true">' + esc(f.nr) + '</div><div class="block" style="top:' + (f.oben || 170) + 'px;width:540px">' + inhalt + '</div>';
    if (v === 'foto_klein') {
      var r = f.foto_rahmen || { x: 560, y: 690, b: 440, h: 440 };
      return '<div class="block" style="top:' + (f.oben || 150) + 'px;width:' + (f.breite || 860) + 'px">' + inhalt + '</div>' +
        '<div class="rahmen hindernis" style="left:' + r.x + 'px;top:' + r.y + 'px;width:' + r.b + 'px;height:' + r.h + 'px">' + img(f.foto) + '</div>';
    }
    /* foto_hintergrund: Foto liegt als Vollbild-Ebene darunter (siehe vollbildEbene), Text links */
    return '<div class="ziffer-umriss" aria-hidden="true">' + esc(f.nr) + '</div><div class="block" style="top:' + (f.oben || 170) + 'px;width:520px">' + inhalt + '</div>';
  },
  speichern: function(f){
    return '<div class="block" style="top:150px">' + (f.marke ? '<p class="marke" style="margin-bottom:30px">' + md(f.marke) + '</p>' : '') +
      '<h2 class="titel">' + zeilen(f.titel || ['Jetzt', '*speichern*']) + '</h2>' +
      '<svg width="120" height="150" viewBox="0 0 120 150" aria-hidden="true"><path d="M10 8 H110 V142 L60 104 L10 142 Z" fill="none" style="stroke:var(--akzent)" stroke-width="10" stroke-linejoin="miter"/></svg>' +
      fliess(f.text) + '</div>';
  },
  zusammenfassung: function(f){
    var li = (f.punkte || []).map(function(t, k){ return '<li><b>' + (k + 1) + '</b>' + md(t) + '</li>'; }).join('');
    return '<div class="block" style="top:150px;width:900px"><h2 class="titel">' + zeilen(f.titel || ['Auf einen *Blick*']) + '</h2><ol>' + li + '</ol></div>' +
      (f.text ? '<div class="block" style="top:' + (f.text_oben || 960) + 'px;width:860px">' + fliess(f.text) + '</div>' : '');
  },
  schluss: function(f, i, plan){
    var logo = plan.branding.logo || {};
    var zeichen = logo.datei ? '<img src="' + esc(logo.datei) + '" alt="' + esc(plan.branding.markenname || '') + '">' :
      '<p class="titel" style="font-size:72px">' + esc(plan.branding.markenname || '') + '</p>';
    return '<div class="medaillon">' + zeichen + '<div class="linie"></div><div class="unterzeile">' + esc(logo.unterzeile || '') + '</div></div>' +
      '<div class="block" style="top:740px"><h2 class="titel">' + zeilen(f.titel) + '</h2>' + fliess(f.text) + '</div>';
  }
};

/* ---------- Uebergaenge (SVG in Leinwand-Koordinaten bzw. gerahmte Fotos) ---------- */
function uebergaenge(plan){
  var svg = [], rahmen = [];
  (plan.uebergaenge || []).forEach(function(u){
    var K = (u.kante || 0) * BREITE, y = u.y || 1080;
    if (u.art === 'zeitstrahl') {
      var x0 = u.start_x != null ? u.start_x : (u.von - 1) * BREITE + 120;
      var x1 = u.ende_x != null ? u.ende_x : (u.bis - 1) * BREITE + 120;
      svg.push('<path class="strich" d="M' + x0 + ' ' + y + ' H' + x1 + '"/>');
      (u.punkte || []).forEach(function(pk, n){
        var folie = typeof pk === 'object' ? pk.folie : pk, lab = typeof pk === 'object' ? pk.label : (n + 1);
        var cx = (folie - 1) * BREITE + 120;
        svg.push('<circle class="punkt" cx="' + cx + '" cy="' + y + '" r="38"/><text x="' + cx + '" y="' + (y + 14) + '" text-anchor="middle">' + esc(lab) + '</text>');
      });
      if (u.ende_punkt) svg.push('<circle class="punkt" cx="' + x1 + '" cy="' + y + '" r="22"/><circle class="ring" cx="' + x1 + '" cy="' + y + '" r="38"/>');
    } else if (u.art === 'treppe') {
      var st = u.stufen || 6, sb = u.stufe_b || 110, sh = u.stufe_h || 53;
      var xs = K - (u.vorlauf || 440), d = 'M' + (u.lead_x != null ? u.lead_x : xs) + ' ' + y + ' H' + xs, yy = y, xx = xs;
      for (var s = 0; s < st; s++) { yy -= sh; d += ' V' + yy; xx += sb; d += ' H' + xx; }
      svg.push('<path class="strich" d="' + d + '"/><circle class="punkt" cx="' + xx + '" cy="' + yy + '" r="22"/><circle class="ring" cx="' + xx + '" cy="' + yy + '" r="38"/>');
    } else if (u.art === 'pfeil') {
      /* Pfeil ueber die Kante, gerade oder steigend */
      var ax = K - (u.vorlauf || 300), bx = K + (u.nachlauf || 240), ay = y + (u.steigung || 0), by = y;
      var wkl = Math.atan2(by - ay, bx - ax), L = 46, Bt = 30;
      var px = bx + Math.cos(wkl) * L, py = by + Math.sin(wkl) * L;
      var lx = bx + Math.cos(wkl + Math.PI / 2) * Bt, ly = by + Math.sin(wkl + Math.PI / 2) * Bt;
      var rx = bx + Math.cos(wkl - Math.PI / 2) * Bt, ry = by + Math.sin(wkl - Math.PI / 2) * Bt;
      svg.push('<path class="strich" d="M' + ax + ' ' + ay + ' L' + bx + ' ' + by + '"/><polygon class="spitze" points="' + [px, py, lx, ly, rx, ry].map(Math.round).join(',') + '"/>');
    } else if (u.art === 'linie') {
      /* Linie laeuft ueber die Kante und knickt nach oben, Punkt am Ende */
      var lx0 = K - (u.vorlauf || 380), lx1 = K + (u.nachlauf || 160), hoch = u.knick || 180;
      svg.push('<path class="strich" d="M' + lx0 + ' ' + y + ' H' + lx1 + ' V' + (y - hoch) + '"/><circle class="punkt" cx="' + lx1 + '" cy="' + (y - hoch) + '" r="20"/>');
    } else if (u.art === 'foto_kante') {
      var b = u.breite || 760, h = u.hoehe || 480;
      rahmen.push('<div class="rahmen hindernis" style="left:' + (K - (u.versatz || 380)) + 'px;top:' + (u.oben || 690) + 'px;width:' + b + 'px;height:' + h + 'px">' + img(u.foto) + '</div>');
    } else if (u.art === 'fotoband') {
      var x = (u.von_folie - 1) * BREITE + 80;
      rahmen.push('<div class="rahmen hindernis" style="left:' + x + 'px;top:' + (u.oben || 760) + 'px;width:' + (2 * BREITE - 160) + 'px;height:' + (u.hoehe || 400) + 'px">' + img(u.foto) + '</div>');
    }
  });
  return { svg: svg.join(''), rahmen: rahmen.join('') };
}

/* ---------- Aufbau ---------- */
function baue(plan){
  var F = plan.folien, N = F.length, W = N * BREITE;
  (plan.fotos || []).forEach(function(f){ FOTOS[f.id] = f; });
  var lw = document.getElementById('leinwand');
  lw.style.width = W + 'px';
  var h = [];
  var kw = plan.kapitelwechsel_nach;
  /* Ebene 0: Grundzonen */
  if (kw) {
    h.push('<div class="zone" style="left:0;width:' + kw * BREITE + 'px;background:var(--grund-1)"></div>');
    h.push('<div class="zone" style="left:' + kw * BREITE + 'px;width:' + (W - kw * BREITE) + 'px;background:var(--grund-2)"></div>');
  } else h.push('<div class="zone" style="left:0;width:' + W + 'px;background:var(--grund-1)"></div>');
  /* Ebene 1 bis 4: Hintergrund */
  var hg = plan.hintergrund || { art: 'raute' };
  if (hg.art === 'foto') h.push('<div class="grund-foto">' + img(hg.foto) + '<div class="ton"></div></div>');
  if (hg.art === 'raute') h.push('<div class="ebene raute"></div>');
  var licht = (hg.licht || [{ x: 420, y: 420 }, { x: W - 540, y: 600 }]).map(function(l){
    return 'radial-gradient(900px 760px at ' + l.x + 'px ' + l.y + 'px, color-mix(in srgb, var(--akzent) ' + (hg.licht_staerke || 6) + '%, transparent), transparent 70%)';
  }).join(',');
  h.push('<div class="ebene licht" style="background:' + licht + '"></div>');
  h.push('<div class="ebene korn' + (hg.art === 'koernung' ? ' stark' : '') + '"></div>');
  /* Ebene 5: Vollbild-Fotos */
  F.forEach(function(f, i){
    if (istVollbild(f)) h.push('<div class="vollbild ' + (f.typ === 'titel' ? 'unten' : 'links') + '" style="left:' + i * BREITE + 'px">' + img(f.foto) + '<div class="ton"></div><div class="verlauf"></div></div>');
  });
  /* Ebene 6 und 7 */
  var u = uebergaenge(plan);
  h.push('<svg class="kante" viewBox="0 0 ' + W + ' ' + HOEHE + '" width="' + W + '" height="' + HOEHE + '" aria-hidden="true">' + u.svg + '</svg>');
  h.push(u.rahmen);
  /* Ebene 8: Inhalte */
  F.forEach(function(f, i){
    var cls = { titel: 't-' + (f.variante || 'typo'), bruecke: 'bruecke', schritt: 'schritt', speichern: 'speichern', zusammenfassung: 'zusammen', schluss: 'schluss' }[f.typ] || '';
    h.push('<section class="folie ' + cls + '" data-typ="' + f.typ + '"' + (f.groesse ? ' data-tg="1"' : '') + ' style="left:' + i * BREITE + 'px' + (f.groesse ? ';--tg:' + (+f.groesse) + 'px' : '') + '">' + BAUSTEIN[f.typ](f, i, plan) + '</section>');
  });
  /* Ebene 9: Folienelemente */
  var el = '';
  for (var i = 1; i <= N; i++) {
    el += '<div class="folie" style="left:' + (i - 1) * BREITE + 'px">';
    if (i < N) el += '<div class="swipe' + (istVollbild(F[i - 1]) ? ' auf-foto' : '') + '">' + (i === 1 ? 'WISCHEN' : '') + '<svg width="52" height="34" viewBox="0 0 52 34" aria-hidden="true"><path d="M4 4 L18 17 L4 30 M24 4 L38 17 L24 30" fill="none" stroke-width="7"/></svg></div>';
    el += '<div class="seite">' + i + '</div><div class="fortschritt">';
    for (var k = 1; k <= N; k++) el += '<span' + (k === i ? ' class="an"' : '') + '></span>';
    el += '</div></div>';
  }
  h.push('<div id="elemente">' + el + '</div>');
  lw.innerHTML = h.join('');
  var folie = Math.min(N, Math.max(1, parseInt(p.get('folie') || '1', 10) || 1));
  lw.style.setProperty('--versatz', folie - 1);
  if (p.get('ohnetext') === '1') document.body.classList.add('ohnetext');
  /* Fehlersuche: ?ohne=raute,korn,licht blendet einzelne Grund-Ebenen aus */
  (p.get('ohne') || '').split(',').forEach(function(e){ if (e) document.querySelectorAll('.leinwand > .' + e).forEach(function(x){ x.style.display = 'none'; }); });
  return N;
}

/* ---------- Pruefmodus: Ueberlauf, Kollision, Textfelder fuer die Kontrastmessung ---------- */
function rgb(c){ var m = c.match(/[\d.]+/g); return m ? m.slice(0, 3).map(Number) : null; }
function pruefe(plan, N){
  var out = { fonts: [], regeln: regeln(plan), meldungen: [], texte: [], n: N };
  var bs = plan.branding.schriften || {};
  out.fonts = [document.fonts.check('700 100px "' + (bs.titel || '') + '"'), document.fonts.check('700 40px "' + (bs.text || '') + '"')];
  var hind = [];
  document.querySelectorAll('.hindernis').forEach(function(e){
    var r;
    if (e.classList.contains('ziffer')) { var rg = document.createRange(); rg.selectNodeContents(e); r = rg.getBoundingClientRect(); }
    else r = e.getBoundingClientRect();
    hind.push({ l: r.left, t: r.top, r: r.right, b: r.bottom, was: e.className });
  });
  /* Linien werden abgetastet (alle 8 px ein Kaestchen), damit eine Treppe nicht als grosses Rechteck zaehlt */
  document.querySelectorAll('.kante path.strich').forEach(function(e){
    var L = e.getTotalLength();
    for (var s = 0; s <= L; s += 8) { var pt = e.getPointAtLength(s); hind.push({ l: pt.x - 9, t: pt.y - 9, r: pt.x + 9, b: pt.y + 9, was: 'kante-linie' }); }
  });
  document.querySelectorAll('.kante circle').forEach(function(e){ var r = e.getBoundingClientRect(); hind.push({ l: r.left, t: r.top, r: r.right, b: r.bottom, was: 'kante-punkt' }); });
  /* Folieninhalte und Folienelemente (WISCHEN, Seitenzahl): beide zaehlen fuer den Kontrast, nur Inhalte fuer Ueberlauf und Kollision */
  var bereiche = [];
  document.querySelectorAll('section.folie').forEach(function(s, i){ bereiche.push({ el: s, idx: i, chrome: false }); });
  document.querySelectorAll('#elemente > .folie').forEach(function(s, i){ bereiche.push({ el: s, idx: i, chrome: true }); });
  bereiche.forEach(function(b){
    var sec = b.el, idx = b.idx, chrome = b.chrome;
    var sl = idx * BREITE;
    var walker = document.createTreeWalker(sec, NodeFilter.SHOW_TEXT, null);
    var n;
    while ((n = walker.nextNode())) {
      if (!n.textContent.trim()) continue;
      var el = n.parentElement;
      if (el.closest('[aria-hidden="true"]') || el.closest('.medaillon') || el.closest('.nummer')) continue;
      var cs = getComputedStyle(el);
      var art = el.closest('.titel, .frage') ? 'titel' : 'text';
      var rg = document.createRange(); rg.selectNodeContents(n);
      Array.prototype.forEach.call(rg.getClientRects(), function(r){
        if (r.width < 2) return;
        var t = { folie: idx + 1, art: art, farbe: rgb(cs.color), px: parseFloat(cs.fontSize), l: Math.round(r.left - sl), t: Math.round(r.top), r: Math.round(r.right - sl), b: Math.round(r.bottom), wort: n.textContent.trim().slice(0, 24) };
        out.texte.push(t);
        if (chrome) return;
        if (t.r > 1000 || t.l < 76) out.meldungen.push('UEBERLAUF folie ' + t.folie + ' "' + t.wort + '" l=' + t.l + ' r=' + t.r);
        if (t.b > 1200) out.meldungen.push('ZU TIEF folie ' + t.folie + ' "' + t.wort + '" unten=' + t.b);
        hind.forEach(function(hd){
          if (r.right > hd.l && r.left < hd.r && r.bottom > hd.t && r.top < hd.b)
            out.meldungen.push('KOLLISION folie ' + t.folie + ' "' + t.wort + '" mit ' + hd.was + ' (text ' + Math.round(r.top) + '-' + Math.round(r.bottom) + ', hindernis ' + Math.round(hd.t) + '-' + Math.round(hd.b) + ')');
        });
      });
    }
  });
  document.body.setAttribute('data-pruef', JSON.stringify(out));
}

/* K1: data-fertig ist das Signal fuer Gotenberg (waitForExpression). Im Pruefmodus wird jede Meldung als Ausnahme geworfen,
   Gotenberg antwortet dann mit 409 und dem Text (failOnConsoleExceptions). Beim Rendern bleibt data-fertig bei einem Fehler aus,
   Gotenberg laeuft in die Zeitgrenze und K1 faellt auf das bisherige Layout zurueck. */
ladePlan().then(function(plan){
  return setzeBranding(plan.branding || {}).then(function(){
    var N = baue(plan);
    return document.fonts.ready.then(function(){
      setTimeout(function(){
        if (p.get('pruefen') === '1') {
          pruefe(plan, N);
          var o = JSON.parse(document.body.getAttribute('data-pruef'));
          var f = o.regeln.concat(o.meldungen);
          if (o.fonts.indexOf(false) >= 0) f.push('SCHRIFT nicht geladen');
          document.body.setAttribute('data-fertig', '1');
          if (f.length) throw new Error('PRUEFMELDUNG ' + f.length + ': ' + f.slice(0, 6).join(' | '));
        } else document.body.setAttribute('data-fertig', '1');
      }, 60);
    });
  });
}).catch(function(e){
  document.body.setAttribute('data-pruef', JSON.stringify({ fehler: String(e) }));
  if (p.get('pruefen') === '1') setTimeout(function(){ document.body.setAttribute('data-fertig', '1'); throw new Error('PRUEFMELDUNG Seite: ' + String(e)); }, 0);
});
})();
</script>
</body>
</html>
`;
const PIXEL = 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7';
const kopf = VORLAGE.replace('<!--SCHRIFTEN-->', () => '<style>' + fontCss + '</style>');
const seite = (plan, abfrage, echt) => {
  const p = JSON.parse(JSON.stringify(plan));
  p.fotos.forEach(f => { const i = parseInt(f.id.slice(1), 10) - 1; f.datei = echt ? fotos[i].uri : PIXEL; });
  p.branding.logo.datei = p.branding.logo.datei ? (echt ? logo : PIXEL) : '';
  return kopf.replace('<!--PLAN-->', () => '<script type="application/json" id="plan">' + JSON.stringify(p).replace(/</g, '\\u003c') + '</script>')
    .replace('/*ABFRAGE*/', () => 'window.__ABFRAGE=' + JSON.stringify(abfrage) + ';');
};
const aus = [];
for (let i = 0; i < plaene.length; i++) {
  const pl = plaene[i];
  const html = seite(pl.plan, 'pruefen=1', false);
  const bin = await helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
  aus.push({ json: { kandidat: i + 1, art: pl.art, versuch: pl.versuch, fingerprint: pl.fp, folien: pl.N, uebergaenge: pl.arten, html_chars: html.length,
    plan: JSON.stringify(pl.plan) }, binary: { index_html: bin }, pairedItem: { item: 0 } });
}
// Warum die Bausteine an Kandidat 1: "Layout 4 Plan wählen" baut daraus die echten Seiten (Fotos, Logo, Schriften), ohne neu zu laden.
aus[0].json.bausteine = { kopf, fotos: fotos.map(f => f.uri), credits: fotos.map(f => f.credit), logo, einzelbild_html: einzelHtml, einzelbild_json: einzel.json,
  gedaechtnis, hinweise, foto_zahl: fotos.length, farben, schriften: { titel: sTitel, text: sText } };
return aus;

// Zweck: aus den Gotenberg-Pruefergebnissen den ersten fehlerfreien Plan nehmen (gewuerfelt 1 bis 5, dann v2) und je Folie
// eine Seite mit Versatz bauen (folie=i im HTML, weil Gotenberg index.html ohne Abfrage laedt, Lauf 767). Dazu das Einzelbild unveraendert.
// Warum Wurf bei keinem Treffer: der Fehlerausgang fuehrt auf das bisherige Layout (Rueckfall altes Layout).
const helpers = this.helpers;
const kand = $('Layout 4 würfeln [Code]').all();
const pr = $input.all();
if (pr.length !== kand.length) throw new Error('L4: ' + pr.length + ' Pruefergebnisse fuer ' + kand.length + ' Plaene');
const b = kand[0].json.bausteine;
const verworfen = [];
let wahl = -1;
for (let i = 0; i < kand.length; i++) {
  const r = pr[i].json || {};
  const sc = Number(r.statusCode || 0);
  if (sc === 200) { wahl = i; break; }
  const text = String(r.data || r.body || (r.error && (r.error.message || r.error)) || '').replace(/\s+/g, ' ');
  verworfen.push('K' + (i + 1) + ' (' + kand[i].json.art + ') ' + (sc || 'ohne Antwort') + ': ' + (text.match(/PRUEFMELDUNG[^:]*:[^"\\]*/) || [text])[0].slice(0, 160));
}
if (wahl < 0) throw new Error('L4: kein Plan bestand den Pruefmodus (' + kand.length + ' geprueft). ' + verworfen.join(' || ').slice(0, 700));
const k = kand[wahl].json;
const plan = JSON.parse(k.plan);
const seite = abfrage => {
  const p = JSON.parse(JSON.stringify(plan));
  p.fotos.forEach(f => { f.datei = b.fotos[parseInt(f.id.slice(1), 10) - 1]; });
  p.branding.logo.datei = p.branding.logo.datei ? b.logo : '';
  return b.kopf.replace('<!--PLAN-->', () => '<script type="application/json" id="plan">' + JSON.stringify(p).replace(/</g, '\\u003c') + '</script>')
    .replace('/*ABFRAGE*/', () => 'window.__ABFRAGE=' + JSON.stringify(abfrage) + ';');
};
const ej = b.einzelbild_json || {};
const ordner = String(ej.path || '').replace(/\/[^\/]*$/, '');
if (!ordner) throw new Error('L4: Ablageordner aus dem Einzelbild nicht lesbar');
const zwei = z => String(z).padStart(2, '0');
const info = { layout: 'instagram_karussell_4', l4_fingerprint: 'L4:' + k.fingerprint, l4_kandidat: wahl + 1, l4_art: k.art, l4_versuch: k.versuch,
  l4_verworfen: verworfen, l4_hinweise: b.hinweise || [], l4_fotos: b.foto_zahl, l4_folien: plan.folien.length };
const aus = [];
for (let i = 1; i <= plan.folien.length; i++) {
  const html = seite('folie=' + i);
  const datei = 'folie-' + zwei(i) + '.png';
  const bin = await helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
  aus.push({ json: Object.assign({ kind: 'folie', platform: 'instagram', format: 'karussell', branding_variant: 'instagram_karussell_4', index: i, file_name: datei, path: ordner + '/' + datei,
    post_id: ej.post_id, customer_code: ej.customer_code, image_source: ej.image_source, image_note: ej.image_note, html_chars: html.length }, info), binary: { index_html: bin }, pairedItem: { item: wahl } });
}
// Warum das Signal im Einzelbild: der Render-Knoten wartet bei allen Seiten auf data-fertig (waitForExpression)
const eh = String(b.einzelbild_html || '');
if (!eh.includes('</body>')) throw new Error('L4: Einzelbild-Seite ohne </body>');
const ebHtml = eh.replace('</body>', () => '<script>document.body.setAttribute("data-fertig","1")</script></body>');
const ebBin = await helpers.prepareBinaryData(Buffer.from(ebHtml, 'utf8'), 'index.html', 'text/html');
aus.push({ json: Object.assign({}, ej, info, { html_chars: ebHtml.length }), binary: { index_html: ebBin }, pairedItem: { item: wahl } });
return aus;

// Zweck: jedes Bild des Layout-4-Laufs pruefen (PNG, 1080 x 1350, Mindestgroesse). Fehlt eins oder ist es kaputt, geht der Lauf
// ueber den Fehlerausgang auf das bisherige Layout (Rueckfall altes Layout), nie mit halben Folien weiter.
const ein = $input.all();
const soll = $('Layout 4 Plan wählen [Code]').all().length;
if (ein.length !== soll) throw new Error('L4: ' + ein.length + ' von ' + soll + ' Bildern zurueck');
const PNG = Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]);
// Warum slide je Folie (12.10.2026): Post speichern legt die Texte des gerenderten Plans ab, nicht die des Pakets, damit Text und Bild je Folie zusammenpassen.
// Warum label: die sichtbare Marke (Schritt N, Fuer spaeter) gehoert zum gerenderten Text.
const rein = s => String(Array.isArray(s) ? s.join(' ') : (s || '')).replace(/\*/g, '').replace(/\s+/g, ' ').trim();
const pw = $('Layout 4 Plan wählen [Code]').first().json;
const plan = JSON.parse($('Layout 4 würfeln [Code]').all()[pw.l4_kandidat - 1].json.plan);
const slideVon = j => { if (j.kind !== 'folie') return {}; const f = plan.folien[j.index - 1] || {}; return { slide: { type: f.typ || '', heading: rein(f.titel || (f.typ === 'speichern' ? 'Jetzt speichern' : '')), text: rein(f.text || f.unter || (f.punkte || []).join(' | ')), label: rein(f.marke || '') } }; };
const aus = [];
for (let i = 0; i < ein.length; i++) {
  const it = ein[i];
  if (!it.binary || !it.binary.bild) throw new Error('L4: Bild ' + (i + 1) + ' ohne Datei (' + String((it.json.error && (it.json.error.message || it.json.error)) || 'Gotenberg ohne Bild').slice(0, 120) + ')');
  const buf = await this.helpers.getBinaryDataBuffer(i, 'bild');
  if (buf.length < 20000 || !buf.subarray(0, 8).equals(PNG)) throw new Error('L4: Bild ' + (i + 1) + ' ist kein PNG oder zu klein (' + buf.length + ' Byte)');
  const b = buf.readUInt32BE(16), h = buf.readUInt32BE(20);
  if (b !== 1080 || h !== 1350) throw new Error('L4: Bild ' + (i + 1) + ' hat ' + b + ' x ' + h + ' statt 1080 x 1350');
  aus.push({ json: Object.assign({}, it.json, { png_bytes: buf.length }, slideVon(it.json)), binary: { bild: it.binary.bild }, pairedItem: { item: i } });
}
return aus;

// Zweck: Rueckfall auf das bisherige Layout (Render-Liste bauen), wenn Layout 4 abgeschaltet ist oder Wuerfeln, Pruefen oder Rendern scheitert.
// Warum layout_note: die Protokollzeile zaehlt den Rueckfall als Ersatzweg mit Grund; bei abgeschaltetem Layout 4 bleibt sie leer.
const f = ($input.first() || { json: {} }).json || {};
const e = f.error;
const grund = String((e && (e.message || e)) || f.message || 'unbekannt').replace(/\s+/g, ' ').slice(0, 220);
const note = /LAYOUT4_AUS/.test(grund) ? '' : 'L4-Rückfall auf bisheriges Layout: ' + grund.replace(/^L4:\s*/, '');
const alt = $('Render-Liste bauen [Code]').all();
if (!alt.length) throw new Error('Rueckfall ohne Render-Liste');
// Warum slide je Folie (12.10.2026): Post speichern legt die Texte genau so ab, wie sie auf den Bildern stehen.
// Gleiche Regel wie Render-Liste bauen: die Ablauf-Folie ersetzt bei 8 Folien die vorletzte, sonst steht sie vor der letzten.
const pk = $('Branding-Variante wählen [Code]').first().json;
const folien = (pk.slides || []).map(x => ({...x}));
if (pk.process_steps != null && Array.isArray(pk.process_steps)) {
  const ablauf = {type: 'ablauf', heading: 'So läuft es ab', schritte: pk.process_steps};
  if (folien.length >= 8) folien.splice(folien.length - 2, 1, ablauf);
  else folien.splice(Math.max(0, folien.length - 1), 0, ablauf);
}
const slideVon = j => { if (j.kind !== 'folie') return {}; const f = folien[j.index - 1] || {}; return { slide: { type: f.type || 'inhalt', heading: String(f.heading || ''), text: String(f.type === 'ablauf' ? (f.schritte || []).join(' | ') : (f.text || '')), cta: String(f.cta || '') } }; };
return alt.map(it => ({ json: Object.assign({}, it.json, { layout_note: note }, slideVon(it.json)), binary: it.binary, pairedItem: { item: 0 } }));

// Zweck (12.10.2026): vor dem Speichern genau die Folien auswaehlen, deren Bilder hochgeladen wurden,
// und Texte und Bildpfade gegeneinander pruefen. Passt etwas nicht, geht der Lauf ueber den Fehlerausgang in F8, statt leere oder verschobene Texte zu speichern.
const cfg = $('Konfiguration und Startzeit [Edit Fields]').first().json;
const keys = Array.isArray($input.first().json.keys) ? $input.first().json.keys : [];
const lief = n => { try { return $(n).isExecuted === true; } catch (e) { return false; } };
// Warum all(0): nur der Erfolgsausgang zaehlt; ein Fehler-Element auf Ausgang 1 darf die Rueckfallfolien nicht verdraengen.
const erfolg = n => { try { return $(n).all(0) || []; } catch (e) { return []; } };
const folie = i => i && i.json && i.json.kind === 'folie' && !i.json.error;
let quelle = '';
let items = [];
// Warum Rueckfall zuerst: lief er, stammen die hochgeladenen Bilder aus dem bisherigen Layout.
if (lief('Rückfall altes Layout [Code]') && erfolg('Rückfall altes Layout [Code]').some(folie)) { quelle = 'rueckfall'; items = erfolg('Rückfall altes Layout [Code]'); }
else if (lief('Layout 4 Ergebnis prüfen [Code]') && erfolg('Layout 4 Ergebnis prüfen [Code]').some(folie)) { quelle = 'layout4'; items = erfolg('Layout 4 Ergebnis prüfen [Code]'); }
else throw new Error('Speichern: keine gerenderten Folien gefunden');
const folien = items.filter(folie).sort((a, b) => a.json.index - b.json.index)
  .map(i => Object.assign({ index: i.json.index, image_path: i.json.path, layout: i.json.branding_variant }, i.json.slide || {}));
const urls = keys.filter(p => String(p).includes('/folie-')).map(p => String(p).replace(cfg.bucket + '/', '')).sort();
const pfade = folien.map(f => f.image_path).sort();
if (folien.length !== urls.length || pfade.some((p, i) => p !== urls[i])) {
  throw new Error('Speichern: ' + folien.length + ' Folientexte fuer ' + urls.length + ' Folienbilder, Zuordnung passt nicht (' + quelle + ')');
}
if (folien.some(f => !f.heading && !f.text)) throw new Error('Speichern: Folie ohne Text (' + quelle + ')');
const einzel = (keys.find(p => String(p).includes('/einzelbild')) || '').replace(cfg.bucket + '/', '');
return [{ json: { keys, slides_saved: folien, slide_urls: urls, single_image_url: einzel, slides_source: quelle } }];
